import{_ as a,o as s,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"90. Practice: Portable Multithreaded Program","description":"The Little Book of C — 90. Practice: Portable Multithreaded Program","frontmatter":{"title":"90. Practice: Portable Multithreaded Program","date":"2026-07-04","categories":"[C 教程]","tags":"[C, Little Book of C, Portable and Modern C]","description":"The Little Book of C — 90. Practice: Portable Multithreaded Program","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":"90","sidebarWeight":"90","lang":"en-US","alternateEn":"/posts/c教程/en-US/09-Portable and Modern C/090-Practice Portable Multithreaded Program","alternateZh":"/posts/c教程/zh-CN/09-可移植与现代 C/090-Practice Portable Multithreaded Program"},"headers":[],"relativePath":"posts/c教程/en-US/09-Portable and Modern C/090-Practice Portable Multithreaded Program.md","filePath":"posts/c教程/en-US/09-Portable and Modern C/090-Practice Portable Multithreaded Program.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/09-Portable and Modern C/090-Practice Portable Multithreaded Program.md"};function l(o,e,p,r,c,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/09-可移植与现代 C/090-Practice Portable Multithreaded Program)</p><h4 id="follow-along-deliverable" tabindex="-1">Follow-Along Deliverable <a class="header-anchor" href="#follow-along-deliverable" aria-label="Permalink to &quot;Follow-Along Deliverable&quot;">​</a></h4><ul><li>Assumed state: lessons 081-089 are complete and you can rebuild the previous example.</li><li>Working directory: <code>~/c-course-labs/090-portable-threads</code>.</li><li>First command: on macOS / Linux run <code>mkdir -p ~/c-course-labs/090-portable-threads &amp;&amp; cd ~/c-course-labs/090-portable-threads</code>; on Windows PowerShell run <code>New-Item -ItemType Directory -Force &quot;$HOME\\c-course-labs\\090-portable-threads&quot;; Set-Location &quot;$HOME\\c-course-labs\\090-portable-threads&quot;</code>.</li><li>Success evidence: keep the source file, executable, <code>evidence.md</code>, and record compiler command, threaded output, and platform or compiler notes.</li><li>Boundary for this lab: This lab focuses on platform differences and concurrency correctness. Windows porting can be recorded as a comparison, but it is not required for the main path.</li><li>Reset: remove the executable, temporary data, and generated output for this lab; keep source and <code>evidence.md</code> for review.</li></ul><p>It’s time to bring together everything you’ve learned, memory management, threads, synchronization, and portability, into one cohesive program.</p><p>In this final section of Chapter 9, you’ll build a portable multithreaded counter that runs correctly across architectures, compilers, and systems, demonstrating clean, safe, and modern C in practice.</p><h4 id="step-1-the-goal" tabindex="-1">Step 1. The Goal <a class="header-anchor" href="#step-1-the-goal" aria-label="Permalink to &quot;Step 1. The Goal&quot;">​</a></h4><p>We’ll write a program that:</p><ul><li>Spawns multiple threads using<code>pthread</code>(POSIX standard).</li><li>Uses atomic operations for safe concurrent updates.</li><li>Prints consistent results regardless of CPU or endianness.</li><li>Compiles cleanly across Linux, macOS, and Windows (via MinGW).</li><li>Uses modern, readable C11–C23 style.</li></ul><h4 id="step-2-plan-the-design" tabindex="-1">Step 2. Plan the Design <a class="header-anchor" href="#step-2-plan-the-design" aria-label="Permalink to &quot;Step 2. Plan the Design&quot;">​</a></h4><ol><li>Shared Counter:<code>atomic_int</code> for thread-safe increments.</li><li>Thread Function: Each thread performs a loop of increments.</li><li>Timing: Measure elapsed time for performance insight.</li><li>Portability: Use<code>#ifdef</code> for cross-platform compatibility.</li><li>Final Validation: Ensure result equals total increments.</li></ol><h4 id="step-3-full-tiny-code" tabindex="-1">Step 3. Full Tiny Code <a class="header-anchor" href="#step-3-full-tiny-code" aria-label="Permalink to &quot;Step 3. Full Tiny Code&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;stdatomic.h&gt;</span></span>
<span class="line"><span>#include &lt;pthread.h&gt;</span></span>
<span class="line"><span>#include &lt;stdint.h&gt;</span></span>
<span class="line"><span>#include &lt;time.h&gt;</span></span>
<span class="line"><span>#ifdef _WIN32</span></span>
<span class="line"><span>#include &lt;windows.h&gt;</span></span>
<span class="line"><span>#define SLEEP(ms) Sleep(ms)</span></span>
<span class="line"><span>#else</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#define SLEEP(ms) usleep((ms) * 1000)</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span>#define THREADS 4</span></span>
<span class="line"><span>#define ITERATIONS 250000</span></span>
<span class="line"><span>atomic_int counter = 0;</span></span>
<span class="line"><span>void* worker(void* arg) {</span></span>
<span class="line"><span>    int id = *(int*)arg;</span></span>
<span class="line"><span>    for (int i = 0; i &lt; ITERATIONS; i++) {</span></span>
<span class="line"><span>        atomic_fetch_add(&amp;counter, 1);</span></span>
<span class="line"><span>        if (i % 100000 == 0 &amp;&amp; id == 0)</span></span>
<span class="line"><span>            SLEEP(1);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return NULL;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>double now(void) {</span></span>
<span class="line"><span>    struct timespec ts;</span></span>
<span class="line"><span>    clock_gettime(CLOCK_MONOTONIC, &amp;ts);</span></span>
<span class="line"><span>    return ts.tv_sec + ts.tv_nsec / 1e9;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    pthread_t threads[THREADS];</span></span>
<span class="line"><span>    int ids[THREADS];</span></span>
<span class="line"><span>    double start = now();</span></span>
<span class="line"><span>    for (int i = 0; i &lt; THREADS; i++) {</span></span>
<span class="line"><span>        ids[i] = i;</span></span>
<span class="line"><span>        if (pthread_create(&amp;threads[i], NULL, worker, &amp;ids[i]) != 0) {</span></span>
<span class="line"><span>            perror(&quot;pthread_create failed&quot;);</span></span>
<span class="line"><span>            return 1;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    for (int i = 0; i &lt; THREADS; i++)</span></span>
<span class="line"><span>        pthread_join(threads[i], NULL);</span></span>
<span class="line"><span>    double end = now();</span></span>
<span class="line"><span>    printf(&quot;Counter = %d (expected %d)\\n&quot;, counter, THREADS * ITERATIONS);</span></span>
<span class="line"><span>    printf(&quot;Elapsed time: %.3f seconds\\n&quot;, end - start);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="step-4-how-it-works" tabindex="-1">Step 4. How It Works <a class="header-anchor" href="#step-4-how-it-works" aria-label="Permalink to &quot;Step 4. How It Works&quot;">​</a></h4><p>Atomic Counter:<code>atomic_fetch_add</code> ensures that increments are atomic and race-free without using a mutex.</p><p>Thread Creation: Each thread runs the<code>worker()</code> function independently.</p><p>Synchronization:<code>pthread_join</code> ensures all threads finish before printing results.</p><p>Timing: Uses<code>clock_gettime()</code> for precise cross-platform timing.</p><p>Sleep Macro:<code>SLEEP(ms)</code> abstracts away platform differences between Windows and POSIX.</p><h4 id="step-5-compile-and-run" tabindex="-1">Step 5. Compile and Run <a class="header-anchor" href="#step-5-compile-and-run" aria-label="Permalink to &quot;Step 5. Compile and Run&quot;">​</a></h4><p>On Linux or macOS:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -std=c23 -pthread -O2 -Wall -Wextra portable_threads.c -o portable_threads</span></span>
<span class="line"><span>./portable_threads</span></span></code></pre></div><p>On Windows (MinGW):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -std=c23 -O2 -Wall -Wextra portable_threads.c -o portable_threads.exe -lws2_32</span></span>
<span class="line"><span>portable_threads.exe</span></span></code></pre></div><p>Expected output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Counter = 1000000 (expected 1000000)</span></span>
<span class="line"><span>Elapsed time: 0.134 seconds</span></span></code></pre></div><p>The program finishes with perfect accuracy, no race conditions, and works across platforms.</p><h4 id="step-6-improving-portability" tabindex="-1">Step 6. Improving Portability <a class="header-anchor" href="#step-6-improving-portability" aria-label="Permalink to &quot;Step 6. Improving Portability&quot;">​</a></h4><p>Replace pthreads with C11<code>&lt;threads.h&gt;</code> if you want standard-only C:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;threads.h&gt;</span></span></code></pre></div><p>Use<code>thrd_create</code> and<code>thrd_join</code> instead of<code>pthread_create</code> and<code>pthread_join</code>.</p><p>Use static assertions for validation:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>_Static_assert(THREADS &gt; 0, &quot;Must have at least one thread&quot;);</span></span></code></pre></div><p>Use conditional macros for system differences (<code>_WIN32</code>,<code>__linux__</code>,<code>__APPLE__</code>).</p><h4 id="step-7-safety-and-clarity-checklist" tabindex="-1">Step 7. Safety and Clarity Checklist <a class="header-anchor" href="#step-7-safety-and-clarity-checklist" aria-label="Permalink to &quot;Step 7. Safety and Clarity Checklist&quot;">​</a></h4><p>✅ No raw pointers shared unsafely ✅ Atomic operations prevent races ✅ Sleep and timing are cross-platform ✅ Clean, modern syntax with C23 support ✅ Easy to modify (e.g., change thread count or workload)</p><h4 id="step-8-why-it-s-portable" tabindex="-1">Step 8. Why It’s Portable <a class="header-anchor" href="#step-8-why-it-s-portable" aria-label="Permalink to &quot;Step 8. Why It’s Portable&quot;">​</a></h4><ul><li>Uses only standard C and POSIX APIs.</li><li>Avoids endian-dependent or undefined behavior.</li><li>Has clear abstractions for platform-specific code.</li><li>Relies on atomic types, not CPU-specific intrinsics.</li><li>Runs on x86, ARM, RISC-V, and others without changes.</li></ul><h4 id="step-9-why-it-matters" tabindex="-1">Step 9. Why It Matters <a class="header-anchor" href="#step-9-why-it-matters" aria-label="Permalink to &quot;Step 9. Why It Matters&quot;">​</a></h4><p>This tiny program embodies what C is best at:</p><ul><li>Speed: Threaded performance close to hardware.</li><li>Control: Explicit memory and concurrency.</li><li>Clarity: Modern C syntax keeps it readable.</li><li>Portability: Runs everywhere a compiler exists.</li></ul><p>This is the C of today, minimal, precise, and reliable.</p><h4 id="step-10-try-it-yourself" tabindex="-1">Step 10. Try It Yourself <a class="header-anchor" href="#step-10-try-it-yourself" aria-label="Permalink to &quot;Step 10. Try It Yourself&quot;">​</a></h4><ol><li>Change<code>THREADS</code> and observe performance scaling.</li><li>Replace the atomic counter with a mutex, compare speed.</li><li>Port it to Windows and verify output.</li><li>Add timing to measure each thread’s duration.</li><li>Experiment with C11<code>&lt;threads.h&gt;</code> API for pure standard C.</li></ol><p>You’ve completed Chapter 9, Portable and Modern C. Next comes Chapter 10: Building Real Projects, where you’ll apply these foundations to construct real-world systems, libraries, servers, and interpreters, all in clean, idiomatic C.</p>`,44)])])}const m=a(i,[["render",l]]);export{u as __pageData,m as default};
